contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // fuzzed amount: the new bet limit to apply
    function testFuzz_property(uint256 amount) public {
        // keep wide domain but avoid trivial overflow concerns (not needed here)
        // Ensure caller is the owner (setUp deployed c with owner = address(this))

        // Call AdjustBetAmounts with fuzzed amount
        bool ok;
        try c.AdjustBetAmounts(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always sets betLimit to the provided amount.
        // We assert that after the call, c.currentBetLimit() == amount and that the call did not revert.
        // This property holds for the correct contract for all inputs; the mutant that increments
        // betLimit instead will violate this for inputs where previous betLimit != 0.
        assertTrue(ok && c.currentBetLimit() == amount);
    }
}

