contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the minimal sequence: read initial, call AdjustDifficulty once, read after
    function check(uint256 amount) public {
        // read initial difficulty
        uint256 before = c.currentDifficulty();

        // call the mutated function once (state-changing call must be top-level)
        c.AdjustDifficulty(amount);

        // read difficulty after
        uint256 after = c.currentDifficulty();

        // The original implementation replaces difficulty: after == before + amount.
        // The mutant increments by amount, which causes after == before + amount as well if called once,
        // but the distinguishing behavior is that in the original AdjustDifficulty can be used to set
        // difficulty to exactly 'amount' when before is 0; to detect the mutant with a single call,
        // require that before is zero by caller so the original sets to amount and mutant increments
        // making after == amount (same) — to distinguish we instead assert that after == amount || after == before + amount
        // But we need a rule that holds on P and is violated by M. To force violation by M, require before == 0
        // then original sets difficulty = amount, but mutant sets difficulty = amount as well (0+amount). That won't distinguish.
        // The true distinguishing property: AdjustDifficulty should set difficulty to exactly amount regardless of prior value.
        // However original replaced prior with amount, mutant makes it additive. Thus the rule: after == amount.

        // Ensure precondition that owner can call AdjustDifficulty isn't needed here because c is assumed deployed and this test runs as owner.
        assert(after == amount);
    }

    // allow contract to receive ETH if needed elsewhere
