pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 1); }

    // General rule: when the owner calls OpenToThePublic(), the contract becomes open to public operations;
    // we verify this by having the fuzzed actor attempt a wager after owner enables the public flag.
    function testFuzz_property(address actor) public {
        // keep actor non-zero and not the zero address
        vm.assume(actor != address(0));

        // fund actor so they can wager
        vm.deal(actor, 1 ether);

        // Owner (the deployer set in setUp) calls OpenToThePublic()
        // This should enable public actions on the reference; the mutant flips it to false.
        bool ok;
        try c.OpenToThePublic() {
            ok = true;
        } catch {
            ok = false;
        }
        // ensure the owner call itself did not revert (both ref and mutant use onlyOwner and owner is this test contract)
        assertTrue(ok);

        // Now, have the fuzzed actor attempt to wager the exact bet limit (1 wei set via constructor param was 1, but betLimit was set to 1 in ctor)
        // Use prank to act as actor and send value; record whether the call succeeds or reverts.
        bool wagerSucceeded;
        vm.prank(actor);
        try c.wager{value: 1}() {
            wagerSucceeded = true;
        } catch {
            wagerSucceeded = false;
        }

        // The single assertion: in the correct contract, after owner calls OpenToThePublic, public actions are enabled,
        // so any actor with funds who calls wager sending the correct amount should be able to wager (wagerSucceeded == true).
        // The mutant flips the flag to false and thus for some actor the wager will fail; the fuzzer will find such an actor.
        assertTrue(wagerSucceeded);
    }
}

