contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 1); }

    // fuzzed params: an address that will act as a player, and a uint256 for betLimit (must be >0)
    function testFuzz_property(address player, uint256 proposedBetLimit) public {
        // Keep a wide admissible domain but ensure a meaningful bet limit
        uint256 betLimit = bound(proposedBetLimit, 1, type(uint256).max);

        // Only the owner (this contract) can call AdjustBetAmounts and OpenToThePublic
        c.AdjustBetAmounts(betLimit);

        // Owner opens to public
        c.OpenToThePublic();

        // Prepare the player EOA with exactly betLimit wei
        vm.deal(player, betLimit);
        vm.prank(player);
        // Player calls wager payable with exactly betLimit
        c.wager{value: betLimit}();

        // The property: after owner opened to public and a real EOA pays exactly betLimit,
        // the contract must record that the player has wagered (hasPlayerWagered == true).
        // This holds in the reference; the mutant that flips the flag to false will break it
        assertTrue(c.hasPlayerWagered(player));
    }
}

