pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 1); }

    // Fuzzed parameters: an address that will act as a player, and a uint256 bet amount.
    // The general rule: when owner calls OpenToThePublic(), a real EOA sending exactly the bet limit
    // can call wager() successfully (and then hasPlayerWagered(player) is true). The mutant flips
    // the boolean and will prevent this for some inputs.
    function testFuzz_property(address player, uint256 bet) public {
        // Keep player as an EOA (fuzzer supplied addresses are EOAs) and not the owner
        vm.assume(player != address(this));
        // Keep bet in a reasonable range and exactly equal to the contract's bet limit (which we set to 1)
        uint256 boundedBet = bound(bet, 1, 1);

        // owner (this) enables public access
        c.OpenToThePublic();

        // fund the player and attempt to wager as that player sending exactly the bet limit
        vm.deal(player, boundedBet);
        vm.prank(player);
        // call wager paying exactly the bet; if openToPublic is true (reference) this should succeed
        // and hasPlayerWagered(player) should be true. If mutant set openToPublic=false, the call reverts
        // and the post-condition will be false.
        bool ok;
        try c.wager{value: boundedBet}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: the reference guarantees that after owner calls OpenToThePublic(),
        // a player paying exactly the bet limit can wager successfully (ok == true). The mutant
        // that sets openToPublic = false will make ok == false for some fuzzed player input.
        assertTrue(ok);
    }
}
